      "causa_raiz": "Alocação massiva e contínua de lixo na memória gerenciada (Managed Heap) durante o Update(). A concatenação repetitiva de strings imutáveis (s += i.ToString()) e a criação de arrays temporários geram mais de 2.6 MB de lixo por frame, forçando coletas síncronas frequentes do Garbage Collector (GC.Collect gastando ~17.94ms). Adicionalmente, chamadas repetidas a FindObjectsOfType<GameObject>() varrem toda a cena e alocam novos arrays de referências a cada frame.",
      "codigo_refatorado": "using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private readonly StringBuilder _reusableStringBuilder = new StringBuilder(4096);
        private static readonly List<GameObject> CachedObjects = new List<GameObject>(512);
        private static MaterialPropertyBlock _propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            if (_propertyBlock == null)
            {
                _propertyBlock = new MaterialPropertyBlock();
            }
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                var emptyGo = new GameObject("Empty_" + i);
                CachedObjects.Add(emptyGo);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _reusableStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _reusableStringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    int count = CachedObjects.Count;
                    for (int j = 0; j < count; j++)
                    {
                        if (CachedObjects[j] != null)
                        {
                            // Operação direta na lista em cache sem busca global
                        }
                    }
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            CachedObjects.Add(clone);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    _propertyBlock.SetColor(ColorPropertyId, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, strings são imutáveis: toda vez que você faz 'texto += algo', a Unity cria uma nova string inteira na memória e descarta a anterior. Multiplicar isso centenas de vezes a cada frame cria montanhas de 'lixo'. Quando a memória do jogo enche, o Garbage Collector pausa o jogo inteiro para limpar a bagunça, causando microtravamentos (stutters) severos. Para evitar isso, reutilizamos buffers existentes com StringBuilder. Além disso, 'GameObject.FindObjectsOfType' vasculha todo o jogo e gera novos arrays toda vez que é chamado; o correto é registrar os objetos em uma List previamente guardada. Por fim, acessar 'renderer.material' cria uma cópia inteira do material na memória de vídeo, enquanto 'MaterialPropertyBlock' permite pintar cada objeto com cores diferentes reaproveitando a mesma base sem gerar cópias desnecessárias."
    }
  ],
  "dicas_level_design": null
}

